INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 1, 'theory', 'Квиз: основы SQL');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 1, 0, 'Что делает звёздочка в запросе SELECT * FROM customers?', '["Выбирает все столбцы таблицы","Выбирает только первую строку","Считает число строк","Умножает значения столбцов"]', 0, 'Звёздочка заменяет список столбцов и означает «все столбцы». Строки при этом отбираются условием, а без условия возвращаются все.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 1, 1, 'Чему равно 7 / 2 в SQLite, если оба числа целые?', '["3.5","4","3","Ошибка деления"]', 2, 'Деление целого на целое отбрасывает дробную часть. Чтобы получить 3.5, одно из чисел нужно записать дробным: 7 / 2.0.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 1, 2, 'Как правильно записать в запросе строку с апострофом: O''Brien?', '["''O\\''Brien''","\"O''Brien\"","''O''''Brien''","''O'' + ''Brien''"]', 2, 'Внутри строки в одинарных кавычках апостроф удваивается. Двойные кавычки в стандарте SQL — для имён, а не для значений.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 1, 3, 'Для чего нужен внешний ключ?', '["Чтобы ускорить сортировку","Чтобы ссылаться на строку другой таблицы","Чтобы запретить пустые значения","Чтобы шифровать данные"]', 1, 'Внешний ключ хранит значение первичного ключа другой таблицы. Так заказ связывается с клиентом, а позиция — с товаром, без копирования данных.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 1, 4, 'Что делает DISTINCT в запросе SELECT DISTINCT city, vip FROM customers?', '["Убирает повторы отдельно в city и отдельно в vip","Убирает строки, где пара значений совпала полностью","Оставляет только VIP-клиентов","Сортирует результат по городам"]', 1, 'DISTINCT работает над строкой результата целиком: одинаковыми считаются строки, у которых совпали все выбранные столбцы.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 2, 'theory', 'Квиз: фильтрация WHERE');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 2, 0, 'Как работает условие a = 1 OR b = 2 AND c = 3?', '["Слева направо: сначала OR, потом AND","Как a = 1 OR (b = 2 AND c = 3): AND связывает сильнее","Как (a = 1 OR b = 2) AND c = 3","Выдаёт ошибку синтаксиса"]', 1, 'AND имеет более высокий приоритет, чем OR. Чтобы получить другую группировку, нужны скобки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 2, 1, 'Какие значения вернёт условие price BETWEEN 1000 AND 5000?', '["Строго от 1000 до 5000, границы не входят","От 1000 включительно, до 5000 не включая","От 1000 до 5000, границы включены","Только значения, равные 1000 или 5000"]', 2, 'BETWEEN эквивалентен price >= 1000 AND price <= 5000: обе границы входят в диапазон.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 2, 2, 'Что найдёт шаблон LIKE ''_ов%''?', '["Строки, содержащие «ов» где угодно","Строки, где вторая и третья буквы — «ов»","Строки длиной ровно три символа","Строки, заканчивающиеся на «ов»"]', 1, 'Подчёркивание заменяет ровно один символ, а % — любую (в том числе пустую) последовательность. Шаблон требует любой первый символ, затем «ов» и что угодно после.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 2, 3, 'Почему запрос SELECT price * 2 AS p2 FROM products WHERE p2 > 100 завершается ошибкой?', '["Псевдоним нельзя называть p2","WHERE выполняется раньше SELECT, и псевдонима ещё нет","Умножение нельзя использовать в SELECT","Нужно написать HAVING вместо WHERE"]', 1, 'Порядок: FROM → WHERE → SELECT. На этапе WHERE псевдоним ещё не вычислен; условие нужно написать через выражение price * 2 > 100.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 2, 4, 'Как в SQLite корректно сравнить дату заказа с первым мая 2024 года?', '["created > ''2024-05-01''","created > 01.05.2024","created > DATE(1.5.2024)","created > 2024/5/1"]', 0, 'Даты хранятся строками ГГГГ-ММ-ДД: алфавитный порядок совпадает с хронологическим, поэтому сравнивать можно как обычные строки.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 3, 'theory', 'Квиз: сортировка и LIMIT');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 3, 0, 'Что произойдёт, если выполнить SELECT * FROM products LIMIT 3 без ORDER BY?', '["Вернутся три самых дешёвых товара","Вернутся любые три строки: какие именно — не гарантируется","Будет ошибка: LIMIT требует ORDER BY","Вернутся три последних записи"]', 1, 'У результата без ORDER BY порядка нет, поэтому LIMIT отрезает произвольные строки. Для топа всегда нужна явная сортировка.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 3, 1, 'Как в SQLite ведёт себя NULL при ORDER BY price ASC?', '["Идёт в конце","Идёт в начале: NULL считается самым маленьким","Исключается из результата","Вызывает ошибку"]', 1, 'В SQLite NULL меньше любого значения: при ASC он первым, при DESC последним. Явно управлять позицией можно через NULLS FIRST / NULLS LAST.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 3, 2, 'Какой запрос вернёт третью страницу по 10 строк?', '["LIMIT 10 OFFSET 30","LIMIT 10 OFFSET 20","LIMIT 30 OFFSET 10","LIMIT 20 OFFSET 10"]', 1, 'Смещение = (номер страницы − 1) × размер страницы = 2 × 10 = 20.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 3, 3, 'Почему для второго ключа сортировки полезно брать уникальный столбец?', '["Это ускоряет запрос в тысячу раз","Порядок строк с одинаковым первым ключом становится однозначным","Без него SQL выдаёт ошибку","Он убирает пустые значения"]', 1, 'Если по первому ключу есть повторы, порядок среди равных не определён. Уникальный второй ключ делает результат воспроизводимым, что важно для страниц и топа.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 3, 4, 'В каком порядке база выполняет части запроса?', '["ORDER BY → WHERE → SELECT → LIMIT","FROM → WHERE → SELECT/DISTINCT → ORDER BY → LIMIT","SELECT → FROM → LIMIT → ORDER BY","LIMIT → ORDER BY → WHERE → FROM"]', 1, 'Сначала FROM и WHERE, затем вычисляется SELECT (и DISTINCT), потом сортировка, и в конце LIMIT/OFFSET. Поэтому ORDER BY видит псевдонимы, а WHERE — нет.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 4, 'theory', 'Квиз: NULL и текст');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 4, 0, 'Запрос SELECT * FROM customers WHERE city <> ''Москва'' не вернул клиента с неуказанным городом. Почему?', '["Это ошибка SQLite","NULL <> ''Москва'' даёт UNKNOWN, а WHERE пропускает только TRUE","Строки с NULL удаляются из таблицы","Нужно писать != вместо <>"]', 1, 'Сравнение с NULL даёт UNKNOWN, и строка отбрасывается. Чтобы включить такие строки, пишут city <> ''Москва'' OR city IS NULL или city IS NOT ''Москва''.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 4, 1, 'Что вернёт COALESCE(NULL, NULL, ''нет'', ''x'')?', '["NULL","''нет''","''x''","Ошибку"]', 1, 'COALESCE возвращает первый аргумент, не равный NULL: это ''нет''.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 4, 2, 'Чему равно ''Анна, '' || NULL?', '["''Анна, ''","''Анна, NULL''","NULL","Пустая строка"]', 2, 'Склейка строки с NULL даёт NULL. Чтобы сохранить подпись, оборачивают значение в COALESCE(город, '''').');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 4, 3, 'Для чего используют NULLIF(x, 0) в знаменателе?', '["Чтобы превратить нуль в NULL и избежать деления на ноль","Чтобы заменить NULL нулём","Чтобы округлить число","Чтобы проверить, что x положительно"]', 0, 'NULLIF(a, b) возвращает NULL, если a равно b. Деление на NULL даёт NULL, а не ошибку.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 4, 4, 'Как выбрать клиентов без указанного города?', '["WHERE city = NULL","WHERE city = ''''","WHERE city IS NULL","WHERE city == 0"]', 2, 'Сравнение = NULL всегда даёт UNKNOWN, поэтому проверку выполняют оператором IS NULL.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 5, 'theory', 'Квиз: агрегатные функции');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 5, 0, 'В таблице 10 клиентов, у 3 из них не указана почта. Чему равен COUNT(email)?', '["10","7","3","0"]', 1, 'COUNT(столбец) считает только непустые значения: 10 − 3 = 7. COUNT(*) вернул бы 10.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 5, 1, 'Значения столбца: 10, NULL, 30. Чему равно AVG?', '["13.33","20","40","NULL"]', 1, 'NULL пропускается и не участвует в делителе: (10 + 30) / 2 = 20.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 5, 2, 'Что вернёт SELECT SUM(total) FROM orders, если подходящих строк нет вообще?', '["0","NULL","Ошибку","Пустой результат без строк"]', 1, 'На пустом наборе SUM возвращает NULL (а COUNT — 0). Чтобы получить 0, используют COALESCE(SUM(total), 0).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 5, 3, 'Почему нельзя написать WHERE SUM(total) > 1000?', '["SUM нельзя применять к числам","WHERE выполняется до агрегации, суммы ещё нет","Нужно писать SUM большими буквами","Знак > нельзя использовать с SUM"]', 1, 'WHERE отбирает строки до свёртки. Условие на значение агрегата записывают в HAVING.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 5, 4, 'Как посчитать число разных городов у клиентов?', '["COUNT(city)","COUNT(DISTINCT city)","SELECT DISTINCT COUNT(city)","SUM(DISTINCT city)"]', 1, 'COUNT(DISTINCT city) убирает повторы перед подсчётом; пропуски тоже не учитываются.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 6, 'theory', 'Квиз: JOIN');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 6, 0, 'Таблицы по 4 и 3 строки соединены без условия (CROSS JOIN). Сколько строк в результате?', '["3","4","7","12"]', 3, 'Декартово произведение: 4 × 3 = 12 пар. Условие соединения нужно, чтобы оставить только осмысленные.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 6, 1, 'Какие клиенты попадут в результат INNER JOIN customers с orders по customer_id?', '["Все клиенты","Только клиенты, у которых есть хотя бы один заказ","Только клиенты без заказов","Клиенты и заказы без клиентов"]', 1, 'INNER JOIN оставляет только пары, для которых условие истинно; клиент без заказов пары не имеет и пропадает.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 6, 2, 'Как найти клиентов, у которых нет ни одного заказа?', '["INNER JOIN … WHERE o.id IS NULL","LEFT JOIN … WHERE o.id IS NULL","RIGHT JOIN … WHERE c.id IS NULL","LEFT JOIN … WHERE o.id = 0"]', 1, 'LEFT JOIN сохраняет всех клиентов; у тех, у кого нет заказов, столбцы заказа NULL — их и оставляет условие IS NULL.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 6, 3, 'Почему WHERE o.status = ''paid'' после LEFT JOIN может «сломать» соединение?', '["Это синтаксическая ошибка","У клиентов без заказов status = NULL, условие не проходит, и они исчезают","WHERE игнорирует правую таблицу","LEFT JOIN нельзя комбинировать с WHERE"]', 1, 'Условие по правой таблице в WHERE отбрасывает строки с NULL, превращая LEFT JOIN во внутреннее. Условие переносят в ON.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 6, 4, 'Заказ стоимостью 100 имеет 3 позиции. Чему равна SUM(o.total) после JOIN с позициями?', '["100","300","33.3","3"]', 1, 'Соединение один ко многим размножает строку заказа: total повторяется три раза. Агрегировать нужно до соединения или считать по уникальным заказам.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 7, 'theory', 'Квиз: подзапросы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 7, 0, 'Как найти товары дороже средней цены всех товаров?', '["WHERE price > AVG(price)","WHERE price > (SELECT AVG(price) FROM products)","HAVING price > AVG(price)","WHERE price IN AVG(price)"]', 1, 'Агрегат нельзя использовать прямо в WHERE; среднее вычисляют скалярным подзапросом и сравнивают с ним.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 7, 1, 'Почему NOT IN (SELECT manager_id FROM employees) может вернуть пустой результат?', '["NOT IN не работает с подзапросами","Если среди manager_id есть NULL, условие никогда не бывает истинным","NOT IN сравнивает только с первым элементом","Подзапрос выполняется несколько раз"]', 1, 'x <> NULL — UNKNOWN, поэтому при NULL в списке выражение NOT IN не бывает истинным. Используйте NOT EXISTS или отфильтруйте NULL.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 7, 2, 'Что означает «коррелированный подзапрос»?', '["Подзапрос, который возвращает много строк","Подзапрос, зависящий от столбцов внешнего запроса","Подзапрос в части FROM","Подзапрос без WHERE"]', 1, 'Коррелированный подзапрос ссылается на столбцы внешней строки и концептуально выполняется для каждой внешней строки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 7, 3, 'Что нужно подзапросу в части FROM?', '["Обязательный LIMIT","Псевдоним","Слово TEMPORARY","Индекс"]', 1, 'Производная таблица должна иметь псевдоним (FROM (SELECT …) AS t), иначе многие базы выдают ошибку.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 7, 4, 'Чем заменить x > ALL (SELECT price …) в SQLite?', '["x > (SELECT MAX(price) …)","x > (SELECT MIN(price) …)","x IN (SELECT price …)","x > (SELECT AVG(price) …)"]', 0, 'Больше всех значений — значит больше максимума. Нужно помнить: для пустого набора MAX даёт NULL, а ALL по стандарту — истину.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 8, 'theory', 'Квиз: INSERT, UPDATE, DELETE');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 8, 0, 'Что произойдёт при выполнении UPDATE products SET price = 0; без WHERE?', '["Ничего: SQLite требует WHERE","Цена станет 0 у всех строк таблицы","Обновится только первая строка","Будет ошибка синтаксиса"]', 1, 'Без WHERE затрагиваются все строки. Перед изменением полезно выполнить SELECT с тем же условием и проверить число строк.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 8, 1, 'Как вставить сразу три строки одной командой?', '["Три раза написать VALUES подряд без запятых","В одном VALUES перечислить три набора значений через запятую","Использовать UPDATE с тремя SET","Это невозможно"]', 1, 'INSERT INTO t (a, b) VALUES (1, 2), (3, 4), (5, 6) добавляет все строки в одной команде; при ошибке не добавится ни одна.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 8, 2, 'Для чего нужна транзакция?', '["Чтобы ускорить SELECT","Чтобы выполнить несколько команд как одно целое: все или ни одной","Чтобы удалить таблицу","Чтобы отсортировать строки"]', 1, 'COMMIT фиксирует изменения всей транзакции, ROLLBACK отменяет всё сделанное с её начала.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 8, 3, 'Что делает INSERT … ON CONFLICT (id) DO UPDATE SET …?', '["Всегда вставляет вторую строку с тем же id","Если строка с таким id уже есть, обновляет её, иначе вставляет","Удаляет конфликтную строку","Откатывает транзакцию"]', 1, 'Это UPSERT: при нарушении уникальности по указанному ключу выполняется обновление вместо ошибки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 8, 4, 'Как узнать номер, который получила только что вставленная строка?', '["Выполнить SELECT MAX(id)","Добавить RETURNING id к INSERT","Выполнить UPDATE","Номер узнать нельзя"]', 1, 'RETURNING возвращает значения вставленной (или изменённой/удалённой) строки прямо из команды; MAX(id) ненадёжен при параллельных вставках.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 9, 'theory', 'Квиз: DDL');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 9, 0, 'Что произойдёт при INSERT без указания значения для столбца INTEGER PRIMARY KEY в SQLite?', '["Ошибка: ключ обязателен","База сама присвоит следующий номер","Вставится NULL","Вставится 0"]', 1, 'INTEGER PRIMARY KEY — псевдоним внутреннего rowid; при отсутствии значения подставляется следующий свободный номер.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 9, 1, 'Чем UNIQUE отличается от PRIMARY KEY?', '["Ничем","В UNIQUE-столбце допускаются NULL (и по стандарту — несколько)","UNIQUE запрещает пропуски, PRIMARY KEY — нет","UNIQUE нельзя использовать с текстом"]', 1, 'Первичный ключ не допускает NULL и в таблице он один. UNIQUE-столбцов может быть несколько, и пропуски в них разрешены.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 9, 2, 'Для чего служит CHECK (price >= 0)?', '["Ускоряет поиск по цене","Отклоняет вставку и изменение, нарушающие условие","Сортирует цены","Заменяет цену нулём"]', 1, 'CHECK — правило для каждой строки: при нарушении условия команда завершается ошибкой.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 9, 3, 'Что делает ON DELETE CASCADE во внешнем ключе?', '["Запрещает удаление родителя","Удаляет зависимые строки вместе с родительской","Обнуляет ссылку","Ничего: это комментарий"]', 1, 'CASCADE каскадно удаляет строки, ссылающиеся на удаляемую; SET NULL обнуляет ссылку, RESTRICT запрещает удаление.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 9, 4, 'Зачем писать CREATE TABLE IF NOT EXISTS?', '["Чтобы таблица создавалась быстрее","Чтобы скрипт можно было запускать повторно без ошибки","Чтобы удалить старую таблицу","Чтобы добавить индекс"]', 1, 'Фраза IF NOT EXISTS делает команду идемпотентной: если таблица уже есть, ничего не произойдёт и ошибки не будет.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 10, 'theory', 'Квиз: CASE WHEN');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 10, 0, 'Что вернёт CASE, если ни одно WHEN не сработало и ветки ELSE нет?', '["0","Пустую строку","NULL","Ошибку"]', 2, 'Без ELSE результатом будет NULL. Поэтому ELSE лучше писать всегда, даже если там NULL.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 10, 1, 'Цена 500. Какую метку вернёт CASE WHEN price < 10000 THEN ''средне'' WHEN price < 1000 THEN ''дёшево'' END?', '["дёшево","средне","NULL","Ошибку"]', 1, 'Ветки проверяются сверху вниз, побеждает первая подошедшая: 500 < 10000, поэтому «средне». Условия ставят от узкого к широкому.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 10, 2, 'Как посчитать число оплаченных заказов условным агрегатом?', '["COUNT(status = ''paid'')","SUM(CASE WHEN status = ''paid'' THEN 1 ELSE 0 END)","CASE SUM(status) WHEN ''paid''","COUNT(*) WHERE paid"]', 1, 'CASE возвращает 1 для подходящих строк и 0 для остальных; SUM складывает единицы. COUNT(выражение) считал бы все непустые значения, в том числе нули.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 10, 3, 'Почему простой CASE x WHEN NULL … не сработает на пустых значениях?', '["NULL нельзя писать в CASE","Простой CASE сравнивает через =, а NULL = NULL — не истина","x должен быть числом","WHEN не принимает константы"]', 1, 'Простая форма сравнивает на равенство, а сравнение с NULL даёт UNKNOWN. Для пропусков нужна поисковая форма с WHEN x IS NULL.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 10, 4, 'Как с помощью CASE расположить статусы в порядке жизненного цикла?', '["ORDER BY CASE status WHEN ''new'' THEN 1 WHEN ''paid'' THEN 2 … END","GROUP BY CASE","WHERE CASE","Это невозможно"]', 0, 'CASE в ORDER BY сопоставляет значениям числа, и сортировка идёт по ним — получается любой нужный порядок.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 11, 'theory', 'Квиз: встроенные функции');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 11, 0, 'Чему равно ROUND(2.5) и ROUND(-2.5) в SQLite?', '["2 и −2","3 и −3","3 и −2","2 и −3"]', 1, 'SQLite округляет половинки «от нуля»: 2.5 → 3, −2.5 → −3. Банковское округление к чётному не применяется.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 11, 1, 'Как получить начало текущего месяца?', '["DATE(''now'', ''start of month'')","DATE(''now'', ''-1 month'')","STRFTIME(''%m'')","DATE(''start of month'')"]', 0, 'Модификатор ''start of month'' сдвигает дату на первое число месяца. Его можно комбинировать с другими: DATE(''now'', ''start of month'', ''-1 month'').');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 11, 2, 'Как посчитать число дней между двумя датами a и b?', '["a - b","JULIANDAY(a) - JULIANDAY(b)","STRFTIME(''%d'', a - b)","DATE(a, b)"]', 1, 'Даты — строки, их нельзя вычитать напрямую. JULIANDAY переводит дату в число дней, разность этих чисел — искомое количество.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 11, 3, 'Что вернёт DATE(''05.05.2024'')?', '["2024-05-05","NULL","Ошибку","Текущую дату"]', 1, 'Функции даты распознают только форматы ISO; для непонятной строки результат — NULL.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 11, 4, 'Как получить ключ месяца «2024-05» из даты d?', '["STRFTIME(''%Y-%m'', d)","MONTH(d)","SUBSTR(d, 5)","DATE(d, ''%Y-%m'')"]', 0, 'STRFTIME с форматом ''%Y-%m'' возвращает год и месяц строкой — удобный ключ для GROUP BY. SUBSTR(d, 1, 7) тоже сработает, но не проверяет формат.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 12, 'theory', 'Квиз: GROUP BY и HAVING');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 12, 0, 'Чем HAVING отличается от WHERE?', '["Ничем, это синонимы","WHERE фильтрует строки до группировки, HAVING — группы по агрегатам после неё","HAVING работает только с текстом","WHERE выполняется после GROUP BY"]', 1, 'WHERE выполняется до группировки и не видит агрегатов; HAVING — после, и условие в нём может использовать COUNT, SUM и другие агрегаты.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 12, 1, 'Какие столбцы допустимо выбирать в запросе с GROUP BY status?', '["Любые столбцы таблицы","status и агрегатные функции","Только агрегатные функции","Только столбцы с уникальными значениями"]', 1, 'В SELECT можно писать ключи группировки и агрегаты. Прочие столбцы не имеют единственного значения для группы (SQLite вернёт произвольное, но это неверно).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 12, 2, 'Как ведут себя NULL в ключе GROUP BY?', '["Отбрасываются","Образуют одну отдельную группу","Каждый NULL — своя группа","Вызывают ошибку"]', 1, 'Для группировки все NULL считаются одинаковыми и попадают в одну группу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 12, 3, 'Каков правильный порядок выполнения частей запроса?', '["SELECT → FROM → WHERE → GROUP BY → HAVING","FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT","FROM → GROUP BY → WHERE → HAVING → SELECT","WHERE → FROM → SELECT → GROUP BY"]', 1, 'Именно этот порядок объясняет, почему в WHERE нельзя использовать агрегаты и псевдонимы, а в ORDER BY можно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 12, 4, 'Почему при группировке итогов по клиентам лучше брать id, а не name?', '["id короче","Разные клиенты могут иметь одинаковое имя и слипнутся в одну группу","name нельзя использовать в GROUP BY","id быстрее сортируется"]', 1, 'Ключ группы должен однозначно определять сущность. Имена могут совпадать, номер — уникален.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 13, 'theory', 'Квиз: индексы и EXPLAIN');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 13, 0, 'Что означает SCAN в плане EXPLAIN QUERY PLAN?', '["Поиск по индексу","Полный перебор таблицы","Сканирование диска на ошибки","Сортировку результата"]', 1, 'SCAN — база читает таблицу строка за строкой. SEARCH … USING INDEX означает переход по индексу к нужным строкам.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 13, 1, 'Индекс создан по (customer_id, created). Какое условие использует его хуже всего?', '["WHERE customer_id = 5","WHERE customer_id = 5 AND created > ''2024-05-01''","WHERE created > ''2024-05-01''","WHERE customer_id IN (1, 2)"]', 2, 'Правило левого префикса: индекс по (a, b) эффективен, когда условие использует a или a и b. Только по b — перебор.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 13, 2, 'Почему WHERE UPPER(name) = ''ИВАН'' не использует обычный индекс по name?', '["UPPER запрещён в WHERE","Функция над столбцом лишает базу возможности искать по упорядоченным значениям","Индекс работает только с числами","Имя слишком короткое"]', 1, 'Индекс хранит значения name, а не UPPER(name). Решение: индекс по выражению UPPER(name) или условие, где столбец стоит сам по себе.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 13, 3, 'Что такое покрывающий индекс?', '["Индекс на все столбцы таблицы","Индекс, содержащий все столбцы, нужные запросу, — таблицу читать не надо","Индекс с проверкой уникальности","Временный индекс"]', 1, 'Если все запрошенные столбцы есть в индексе, база берёт значения прямо из него (USING COVERING INDEX).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 13, 4, 'Какой столбец почти бесполезно индексировать?', '["email (уникальный)","customer_id во внешнем ключе","vip со значениями 0 и 1","created (дата заказа)"]', 2, 'Низкая селективность: условие вернёт половину таблицы, и перебор всех строк выгоднее перехода по индексу.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 14, 'theory', 'Квиз: общие табличные выражения');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 14, 0, 'Как записывается общее табличное выражение?', '["WITH имя AS (SELECT …) SELECT … FROM имя","CREATE TABLE имя AS …","SELECT … AS WITH имя","TEMP имя (SELECT …)"]', 0, 'Перед основным запросом пишут WITH, имя, AS и в скобках SELECT; затем на имя ссылаются как на таблицу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 14, 1, 'Какое преимущество CTE перед подзапросом во FROM?', '["CTE всегда быстрее","Читаемость и возможность ссылаться на результат несколько раз","CTE сохраняет данные навсегда","CTE можно использовать без SELECT"]', 1, 'CTE получает имя, читается сверху вниз и может быть использовано в запросе многократно. Скорость сама по себе не меняется.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 14, 2, 'Из каких частей состоит рекурсивное CTE?', '["Только из SELECT","Стартовая часть и рекурсивная часть, соединённые UNION ALL","Из двух независимых запросов с JOIN","Из цикла FOR"]', 1, 'Стартовая часть даёт первые строки, рекурсивная порождает следующие из уже полученных; соединяются через UNION [ALL].');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 14, 3, 'Что произойдёт при рекурсии без условия остановки на данных с циклом?', '["Запрос вернёт пустой результат","Рекурсия не завершится (до лимита или таймаута)","База сама оборвёт цикл на второй итерации","Запрос выдаст синтаксическую ошибку"]', 1, 'Нужны защита: условие по глубине, UNION вместо UNION ALL или проверка пройденного пути.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 14, 4, 'Для чего служит рекурсивное CTE в запросах?', '["Для ускорения запросов","Для генерации рядов и обхода иерархий","Для создания индексов","Для записи данных в таблицу"]', 1, 'Рекурсия строит ряды чисел и дат и обходит деревья: сотрудников, категории, папки.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 15, 'theory', 'Квиз: оконные функции');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 15, 0, 'Чем оконная функция отличается от агрегатной с GROUP BY?', '["Ничем","Не схлопывает строки: результат считается для каждой строки отдельно","Работает только с числами","Работает быстрее"]', 1, 'GROUP BY превращает группу в одну строку, а оконная функция оставляет все строки и добавляет вычисленный столбец.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 15, 1, 'Что вернёт SUM(x) OVER (ORDER BY id) для значений x: 10, 20, 30?', '["60, 60, 60","10, 30, 60","10, 20, 30","30, 50, 60"]', 1, 'С ORDER BY рамка по умолчанию — от начала окна до текущей строки: получаем накопительный итог 10, 30, 60.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 15, 2, 'Значения в рейтинге: 90, 85, 85, 70. Какие места выдаст RANK() по убыванию?', '["1, 2, 3, 4","1, 2, 2, 4","1, 2, 2, 3","1, 1, 1, 1"]', 1, 'RANK даёт равным одинаковое место и пропускает следующее: 1, 2, 2, 4. DENSE_RANK дал бы 1, 2, 2, 3, а ROW_NUMBER — 1, 2, 3, 4.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 15, 3, 'Как получить три самых дорогих товара в каждой категории?', '["LIMIT 3","ROW_NUMBER() OVER (PARTITION BY category ORDER BY price DESC) в подзапросе/CTE и условие rn <= 3 снаружи","GROUP BY category HAVING COUNT(*) <= 3","ORDER BY category LIMIT 3"]', 1, 'LIMIT ограничивает весь результат. Нумерацию внутри групп делает оконная функция, а условие на неё нужно писать во внешнем запросе.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 15, 4, 'Что возвращает LAG(x) для первой строки окна?', '["0","NULL","Значение самой первой строки","Ошибку"]', 1, 'Предыдущей строки нет, поэтому LAG возвращает NULL, если третьим аргументом не задано значение по умолчанию.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 16, 'theory', 'Квиз: представления');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 16, 0, 'Хранит ли представление (VIEW) данные?', '["Да, как копию таблицы","Нет, только текст запроса, выполняемый при обращении","Только первые 1000 строк","Только при наличии индекса"]', 1, 'Обычное представление хранит лишь определение запроса; данные всегда берутся из таблиц, поэтому они свежие.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 16, 1, 'Как изменить представление в SQLite?', '["ALTER VIEW","CREATE OR REPLACE VIEW","DROP VIEW и CREATE VIEW заново","UPDATE VIEW"]', 2, 'В SQLite нет ALTER VIEW и OR REPLACE: представление удаляют и создают заново, лучше в одной транзакции.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 16, 2, 'Можно ли вставлять строки через представление в SQLite?', '["Да, всегда","Нет: представления только для чтения; запись — через INSTEAD OF-триггеры","Только если нет JOIN","Только если есть индекс"]', 1, 'Представления SQLite доступны только для чтения. Для записи создают INSTEAD OF-триггер, перехватывающий операцию.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 16, 3, 'Чем опасна звёздочка в определении представления?', '["Запрещена синтаксисом","Раскрывается один раз при создании: новые столбцы таблицы в нём не появятся","Замедляет запросы в 10 раз","Выбирает только числовые столбцы"]', 1, 'Список столбцов фиксируется при создании. Лучше перечислять столбцы явно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 16, 4, 'Что происходит с индексами таблиц при запросе к представлению?', '["Не используются","Работают: запрос разворачивается в запрос к таблицам","Используются только уникальные","Индексы нужно создавать для представления"]', 1, 'SQLite встраивает определение представления в запрос; индексы нижележащих таблиц применяются как обычно.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 17, 'theory', 'Квиз: реляционная модель и запросы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 17, 0, 'Запрос WHERE city = NULL ничего не вернул, хотя в таблице есть клиенты без города. Почему?', '["NULL нужно писать маленькими буквами","Сравнение с NULL даёт «неизвестно», а не истину: нужен IS NULL","Столбец city имеет неподходящий тип","WHERE не умеет работать со строками"]', 1, 'NULL означает «не задано»; любое сравнение с ним — UNKNOWN, и такие строки отбрасываются. Для проверки используют IS NULL и IS NOT NULL.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 17, 1, 'Что вернёт запрос с условием x NOT IN (1, 2, NULL)?', '["Все строки, где x не равен 1 и 2","Ошибку: NULL в списке запрещён","Только строки, где x равен NULL","Ни одной строки: для любого x условие даёт UNKNOWN"]', 3, 'x <> NULL — неизвестно, а конъюнкция с неизвестным не бывает истинной. Поэтому NOT IN с NULL в списке всегда пуст; используют NOT EXISTS или убирают NULL.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 17, 2, 'После LEFT JOIN orders вы дописали WHERE orders.status = ''paid'', и клиенты без заказов пропали. Что произошло?', '["Строки с NULL справа не прошли условие, и соединение фактически стало внутренним","LEFT JOIN нельзя комбинировать с WHERE","База удалила клиентов без заказов","Условие применилось к левой таблице"]', 0, 'Для клиента без заказа orders.status равен NULL, а NULL = ''paid'' — неизвестно. Условие по правой таблице, которое не должно убирать левые строки, пишут в ON.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 17, 3, 'Сумма заказа после соединения с позициями и платежами получилась втрое больше. Как правильно исправить?', '["Применить DISTINCT ко всей сумме","Заменить JOIN на LEFT JOIN","Свернуть позиции и платежи отдельно до одной строки на заказ и только потом соединить","Добавить ORDER BY перед SUM"]', 2, 'Каждое соединение размножает строки, и агрегат считает дубликаты. Сначала агрегируют каждую ветку (подзапрос или WITH), затем соединяют результаты.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 17, 4, 'В чём разница между WHERE и HAVING?', '["Никакой, это синонимы","WHERE отбирает строки до группировки, HAVING — группы после неё и может использовать агрегаты","HAVING работает только с числами","WHERE быстрее на любых данных"]', 1, 'Логический порядок: FROM → WHERE → GROUP BY → HAVING → SELECT. Поэтому агрегат в WHERE нельзя, а в HAVING — можно.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 18, 'theory', 'Квиз: транзакции и изоляция');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 18, 0, 'Две транзакции прочитали баланс 100 и каждая записала 110 (+10 в приложении). Как называется аномалия и как её лечат?', '["Грязное чтение — повышением уровня до READ UNCOMMITTED","Фантом — добавлением индекса","Взаимоблокировка — уменьшением таймаута","Потерянное обновление — атомарным UPDATE bal = bal + 10 или блокировкой строки"]', 3, 'Шаблон «прочитать, изменить в приложении, записать» теряет одно из изменений. Арифметику выполняют в базе одним запросом, либо блокируют строку (FOR UPDATE), либо проверяют версию.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 18, 1, 'Что означает уровень изоляции REPEATABLE READ?', '["Каждый запрос видит самые свежие зафиксированные данные","Снимок данных фиксируется на всю транзакцию: повторное чтение строки даёт то же значение","Транзакции выполняются строго по очереди","Разрешено читать чужие незафиксированные изменения"]', 1, 'READ COMMITTED берёт новый снимок на каждый запрос, REPEATABLE READ — один на транзакцию, SERIALIZABLE гарантирует результат как при последовательном исполнении.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 18, 2, 'Как MVCC позволяет читателям не блокировать писателей?', '["Каждое изменение создаёт новую версию строки, а читатель видит версии из своего снимка","Писатель ждёт, пока читатель закончит","Читатели получают копию всей таблицы","Писатели работают только ночью"]', 0, 'Старая версия остаётся, пока нужна чьему-то снимку; ненужные версии позже убирает фоновая очистка (vacuum в PostgreSQL).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 18, 3, 'Транзакция T1 держит строку A и ждёт B, а T2 держит B и ждёт A. Что делает база?', '["Ждёт бесконечно","Объединяет транзакции в одну","Находит цикл в графе ожидания и откатывает одну из транзакций (дедлок)","Игнорирует блокировки"]', 2, 'Главный способ избежать дедлоков — брать блокировки в одном порядке и держать транзакции короткими; приложение повторяет откатанную транзакцию.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 18, 4, 'Почему COMMIT подтверждается только после fsync журнала (WAL)?', '["Чтобы ускорить чтение","Чтобы подтверждённая транзакция пережила падение питания: после сбоя журнал проигрывается заново","Чтобы не использовать индексы","Это требование ограничений CHECK"]', 1, 'Страницы данных могут попасть на диск позже; журнал — источник истины для восстановления. Отключение fsync ускоряет коммит, но риск потерять подтверждённое возвращается.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 19, 'theory', 'Квиз: индексы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 19, 0, 'Есть составной индекс по (city, created). Какой запрос сможет им воспользоваться эффективно?', '["WHERE city = ''Москва'' AND created >= ''2024-02-01''","WHERE created = ''2024-02-01''","WHERE city LIKE ''%ква''","WHERE lower(city) = ''москва''"]', 0, 'Работает левый префикс: сначала равенство по city, затем диапазон по created. Запрос только по created, ведущий % и функция над столбцом индекс не используют.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 19, 1, 'Почему B-дерево с миллиардом ключей остаётся очень низким?', '["Потому что ключи сжимаются","Потому что дерево хранится в оперативной памяти целиком","Потому что в странице помещаются сотни ключей — ветвистость велика, и хватает 3–4 уровней","Потому что дерево перестраивается при каждом чтении"]', 2, 'Глубина ≈ log по основанию ветвистости: при 300 потомках на узел три уровня дают десятки миллионов строк, четыре — миллиарды.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 19, 2, 'Что означает «COVERING INDEX» в плане запроса?', '["Индекс покрывает всю таблицу и поэтому дорог","Все нужные запросу столбцы есть в индексе, и в таблицу заглядывать не нужно","Индекс создан автоматически","Запрос не использует ни индексов, ни таблицы"]', 1, 'Покрывающий индекс избавляет от чтения таблицы (index-only scan), но шире и дороже в обновлении: его заводят для самых горячих запросов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 19, 3, 'Что плохого в постраничном выводе через OFFSET 100000?', '["Ничего, база просто переходит к нужной строке","OFFSET запрещён в SQL","OFFSET отключает сортировку","База читает и выбрасывает все предыдущие строки, и глубокие страницы становятся медленными"]', 3, 'Keyset-пагинация запоминает последний ключ и использует условие «после него» — индекс даёт одинаковую цену на любой странице.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 19, 4, 'Почему нельзя просто создать индекс на каждый столбец «на всякий случай»?', '["Индексы запрещены в таблицах с внешними ключами","Индексы работают только по одному на таблицу","Каждый индекс замедляет вставки и изменения и занимает место, а многие никогда не будут использованы","Из-за индексов запросы возвращают неверные данные"]', 2, 'Усиление записи: изменение строки обновляет все её индексы. Индекс заводят под конкретный частый запрос и периодически чистят неиспользуемые и дублирующие.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 20, 'theory', 'Квиз: хранилища');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 20, 0, 'Почему коммит в базе с журналом упреждающей записи быстр, хотя данные на диске ещё не обновлены?', '["Потому что база не пишет на диск вообще","Достаточно последовательно сбросить журнал на диск; страницы данных запишутся позже, а после сбоя журнал проиграют заново","Потому что журнал хранится в оперативной памяти","Потому что коммит откладывается до следующей перезагрузки"]', 1, 'Журнал пишется только в конец — это быстро, и он содержит всё, чтобы восстановить изменения. Страницы можно записывать в удобное время и в любом порядке.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 20, 1, 'Что делает LSM-дерево при записи?', '["Обновляет нужную страницу на месте","Сразу перестраивает индекс на диске","Пишет в журнал и в memtable в памяти, а затем сбрасывает её на диск неизменяемым отсортированным файлом; потом фоновая компакция сливает файлы","Записывает каждое изменение во все файлы"]', 2, 'Запись всегда последовательная. Платой становятся фоновая компакция и более сложное чтение — значение может лежать в любом из нескольких файлов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 20, 2, 'Зачем у каждого файла LSM-дерева держат фильтр Блума?', '["Чтобы быстро ответить «точно нет» и не читать файл, где ключа заведомо нет","Чтобы сжимать данные","Чтобы шифровать файл","Чтобы определять порядок записи"]', 0, 'Фильтр допускает ложные «возможно есть», но не допускает ложных «нет»: лишние чтения исчезают, а правильные — остаются.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 20, 3, 'Почему аналитические запросы выигрывают от колоночного хранения?', '["Потому что все значения строки лежат рядом","Потому что столбцы нельзя изменять","Потому что колонки не требуют журнала","Запрос читает только нужные столбцы, а однотипные значения хорошо сжимаются"]', 3, 'Среднее по одному столбцу из сотни читает 1 % данных; повторы заменяются парой «значение — число повторов», строки — числами через словарь.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 20, 4, 'Что гарантирует вызов fsync?', '["Что запись попала в кэш операционной системы","Что данные физически записаны на устройство и переживут сбой питания","Что файл зашифрован","Что файл больше не изменится"]', 1, 'write() возвращается, когда данные в кэше ОС. Без fsync подтверждённый коммит можно потерять; поэтому коммит и ждёт сброса журнала.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 21, 'theory', 'Квиз: нереляционные базы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 21, 0, 'Почему в хранилище ключ—значение нельзя запросить «всех пользователей из Казани»?', '["Потому что город — не строка","Потому что запросы запрещены лицензией","Значение для базы чёрный ящик: запросов по содержимому нет, а только доступ по ключу","Потому что ключи обязаны быть числами"]', 2, 'Решение — заранее построить нужный ключ или вторую запись-указатель и поддерживать её приложением; либо выбрать документную базу с индексами по полям.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 21, 1, 'Когда в документной базе лучше сослаться по идентификатору, а не вложить данные?', '["Когда данные общие для многих документов и часто меняются — иначе придётся обновлять их повсюду","Когда данные читаются всегда вместе и почти не меняются","Никогда: ссылки запрещены","Когда документ слишком короткий"]', 0, 'Вложение даёт быстрое чтение, но дублирует факт. Общее и часто меняющееся (название товара, цена) держат в одном месте и подтягивают вторым запросом.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 21, 2, 'Что значит «моделирование от запросов» в Cassandra?', '["Сначала создаются таблицы, потом придумываются запросы","Для каждого типа запроса заводят свою таблицу с подходящим ключом, дублируя данные","Все данные хранят в одной таблице без ключа","Запросы выполняются в приложении"]', 1, 'Соединений нет, поэтому один и тот же факт хранят в нескольких таблицах под разные ключи; следят за размером партиции и горячими ключами.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 21, 3, 'Чем граф выигрывает у цепочки JOIN в задаче «друзья друзей друзей»?', '["Граф хранит узлы без связей","В графе нет индексов","Граф всегда быстрее для агрегатов","Узел хранит прямые ссылки на соседей, и переход по ребру почти бесплатен, а каждый JOIN удорожает запрос"]', 3, 'Графовые базы оптимизированы под обход связей; платой становится сложность горизонтального масштабирования и агрегатов по всей коллекции.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 21, 4, 'Что хранит инвертированный индекс поискового движка?', '["Для каждого документа список его слов в исходном порядке","Для каждого слова — список документов, где оно встречается","Только заголовки документов","Хеши документов"]', 1, 'Запрос разбивается на слова, по каждому берётся список документов, списки пересекаются или объединяются и ранжируются по релевантности.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 22, 'theory', 'Квиз: репликация');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 22, 0, 'Пользователь изменил имя и сразу открыл профиль, но видит старое имя. Что произошло и чем лечат?', '["Лидер потерял запись; лечат полной перезагрузкой","Чтение попало на отстающую реплику; лечат чтением с лидера после записи или токеном LSN","Кэш браузера; лечат сбросом куков","Дедлок; лечат повтором транзакции"]', 1, 'Это нарушение гарантии «чтение собственных записей». Читают с лидера для свежих изменений либо только с реплик, которые уже применили номер записи клиента.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 22, 1, 'Что такое split-brain и как с ним борются?', '["Потеря журнала; борются бэкапом","Раскол индекса; борются перестройкой","Два узла одновременно считают себя лидерами; борются номерами эпох, ограждением (fencing) и консенсусом","Рассинхронизация часов; борются NTP"]', 2, 'Запись с номером эпохи прошлого лидера отвергается хранилищем; выбор лидера большинством (Raft) исключает двух лидеров в одну эпоху.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 22, 2, 'При N = 3 запись подтверждается двумя репликами, чтение опрашивает две. Гарантирует ли это свежее чтение?', '["Нет: нужно опрашивать все три","Нет: кворумы не работают без лидера","Да, но только при синхронных часах","Да: W + R = 4 > N = 3, чтение пересечётся с репликой, где есть последняя запись"]', 3, 'Пересечение множеств гарантирует, что среди опрошенных есть хотя бы одна свежая реплика; клиент выбирает значение с наибольшей версией.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 22, 3, 'Две версии записи имеют векторы {A:3, B:1} и {A:2, B:2}. Что это значит?', '["Первая новее","Версии параллельны — произошёл настоящий конфликт, нужно слить","Вторая новее","Версии равны"]', 1, 'Ни один вектор не меньше другого по всем компонентам: изменения возникли независимо. Новее — только когда все счётчики не меньше.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 22, 4, 'Почему репликация не заменяет резервное копирование?', '["Потому что реплики медленнее","Потому что реплики хранят только индексы","Потому что случайное удаление или порча данных мгновенно реплицируется на все копии","Потому что бэкап шифруется"]', 2, 'Нужна копия на прошлый момент времени с журналом изменений. Для защиты от человеческих ошибок иногда держат реплику с намеренной задержкой.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 23, 'theory', 'Квиз: шардирование');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 23, 0, 'Почему шардирование по hash(key) mod N плохо переносит добавление шарда?', '["Хеш перестаёт быть равномерным","Нужно перестраивать индексы","Остаток от деления меняется почти у всех ключей — переезжает основная часть данных","Нельзя изменить число шардов"]', 2, 'Консистентное хеширование решает это: при добавлении узла к нему переходит лишь часть ключей соседа (≈ 1/N), остальные остаются на местах.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 23, 1, 'Что плохого в диапазонном шардировании по автоинкрементному id?', '["Все новые записи попадают в последний шард — он перегружен, остальные простаивают","Диапазонные запросы нельзя выполнять","Нельзя создать индекс","Ключи занимают слишком много места"]', 0, 'Монотонный ключ создаёт горячую точку в хвосте; помогает хеш, составной ключ или разбиение диапазона так, чтобы запись шла в разные шарды.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 23, 2, 'Для чего нужны виртуальные узлы в консистентном хешировании?', '["Чтобы шифровать данные","Чтобы физический узел занимал несколько мест на кольце и нагрузка распределялась ровнее","Чтобы ускорить сеть","Чтобы хранить копии резервных копий"]', 1, 'Несколько мест на кольце сглаживают случайные перекосы и при отказе узла распределяют его нагрузку между многими соседями.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 23, 3, 'Чем неприятен запрос без ключа шардирования?', '["Он невозможен","Он обходит индексы","Он нарушает репликацию","Он выполняется на всех шардах, и время ответа определяется самым медленным"]', 3, 'Scatter-gather нагружает всю систему и усиливает хвосты задержек; поэтому ключ выбирают по самым частым запросам.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 23, 4, 'В чём главный недостаток двухфазной фиксации (2PC)?', '["Нельзя использовать с индексами","Если координатор упал между фазами, участники ждут, удерживая блокировки","Она не гарантирует атомарность","Она работает только на одном шарде"]', 1, 'Поэтому в распределённых системах часто используют саги — цепочки локальных транзакций с компенсирующими действиями.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 24, 'theory', 'Квиз: согласованность');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 24, 0, 'Что утверждает теорема CAP для сети, которая раскололась на две части?', '["Система обязана остановиться","Приходится выбирать: отказывать части запросов ради согласованности или отвечать, возможно, устаревшими данными ради доступности","Данные автоматически синхронизируются","Разделение не влияет на выбор"]', 1, 'Разделения в сети неизбежны, поэтому реальный выбор — между CP и AP; PACELC добавляет, что и без разделения приходится выбирать между задержкой и согласованностью.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 24, 1, 'Что гарантирует линеаризуемость?', '["Все операции выполняются на одной машине","Часы всех узлов совпадают","Записи никогда не конфликтуют","Система ведёт себя как одна копия: завершённая запись видна любому чтению, начавшемуся позже"]', 3, 'Гарантия сильная и интуитивная, но требует согласования узлов — это задержка и недоступность при разделении; поэтому её применяют там, где важно «кто первый».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 24, 2, 'Чем причинная согласованность отличается от итоговой?', '["Причинная гарантирует, что следствие не будет видно раньше причины; итоговая обещает лишь сходимость со временем","Ничем","Причинная работает только на одном узле","Итоговая сильнее причинной"]', 0, 'Причинная модель остаётся доступной при разделении и сохраняет разумный порядок; итоговая не гарантирует ни порядок, ни скорость сходимости.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 24, 3, 'Как работают часы Лампорта?', '["Берут время из NTP","Складывают время всех узлов","При получении сообщения счётчик становится max(свой, пришедший) + 1: причина всегда имеет меньший номер","Измеряют скорость сети"]', 2, 'Логические часы не зависят от расхождения физических часов и сохраняют причинный порядок событий.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 24, 4, 'Как получить эффект «ровно один раз» при ненадёжной доставке?', '["Отправлять сообщение один раз","Доставлять хотя бы раз, а получатель обрабатывает идемпотентно по уникальному идентификатору операции","Отключить повторы","Использовать более быструю сеть"]', 1, 'Повтор с тем же id не меняет результат; паттерн outbox делает отправку события атомарной с изменением данных.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 25, 'theory', 'Квиз: кэш');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 25, 0, 'Как работает кэш сбоку (cache-aside) при чтении и записи?', '["При чтении: кэш, при промахе — база и запись в кэш; при записи: изменение базы и удаление или обновление записи в кэше","Приложение пишет только в кэш, а база обновляется сама","Кэш сам читает базу при каждом запросе и пишет в неё","Оба хранилища обновляются независимыми процессами без участия приложения"]', 0, 'Кэш не обязан быть надёжным: потерянный кэш — это холодный старт. Недостаток — логика кэширования живёт в приложении, и забытая инвалидация даёт устаревшие данные.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 25, 1, 'Что такое cache stampede и как с ним бороться?', '["Переполнение памяти кэша; нужно больше памяти","Отказ сети; нужны реплики","Одновременный промах популярной записи, когда тысячи запросов идут в базу; лечат единственным пересчётом, ранним обновлением и джиттером TTL","Сбой часов; нужен NTP"]', 2, 'Первый запрос берёт блокировку и пересчитывает значение, остальные ждут или получают слегка устаревшее; случайный разброс срока не даёт записям истекать пачкой.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 25, 2, 'Какая беда может случиться при ключе кэша без идентификатора пользователя для персональных данных?', '["Кэш не сможет вытеснять записи","Один пользователь увидит ответ, предназначенный другому — утечка данных","Кэш станет медленнее","TTL перестанет работать"]', 1, 'Ключ должен быть функцией всех параметров запроса: язык, валюта, права и пользователь. Иначе кэш смешивает ответы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 25, 3, 'Что даёт кэширование отрицательного результата и фильтр Блума?', '["Ускоряют запись","Уменьшают размер значений","Шифруют ключи","Защищают базу от запросов по несуществующим ключам, которые всегда мимо кэша"]', 3, 'Запоминаем «такого нет» на короткое время; для огромных пространств ключей фильтр Блума быстро отвечает «точно нет» и не пускает запрос в базу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 25, 4, 'Доля попаданий в кэш 90 %. Что это означает для нагрузки на базу?', '["Она не изменилась","Она упала примерно в десять раз: в базу уходят лишь промахи","Она выросла","Она упала на 90 раз"]', 1, 'В базу идёт 10 % запросов. Поэтому hit ratio — главная метрика кэша; низкая доля попаданий означает, что кэш только добавляет задержку и сложность.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 26, 'theory', 'Квиз: OLTP и OLAP');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 26, 0, 'Чем запросы OLAP отличаются от запросов OLTP?', '["Меняют по одной строке по индексу за миллисекунды","Читают много строк, но мало столбцов, и сворачивают их в небольшой результат","Не используют эс-кью-эль","Работают только с одной таблицей без соединений"]', 1, 'OLTP — короткие точечные операции по строкам, OLAP — скан миллионов строк и агрегация; поэтому им нужны разные хранилища.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 26, 1, 'Почему аналитику на основной базе приходится ограничивать?', '["Эс-кью-эль запрещает агрегаты","Аналитические данные нельзя хранить в таблицах","База не умеет GROUP BY","Тяжёлый скан вытесняет горячие страницы из памяти, занимает диск, а долгие транзакции мешают очистке версий"]', 3, 'Для небольших отчётов хватает читающей реплики; для больших нагрузок строят отдельное хранилище.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 26, 2, 'Что такое схема «звезда»?', '["Таблица фактов в центре и таблицы измерений вокруг неё","Одна таблица без ключей","Граф зависимостей между индексами","Кольцо узлов с консистентным хешированием"]', 0, 'Факты — события с числами, измерения — описательные справочники; денормализация измерений уменьшает число соединений.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 26, 3, 'Почему повторный запуск загрузки должен быть идемпотентным?', '["Чтобы загрузка работала быстрее","Чтобы не нужны были индексы","Чтобы повтор той же порции не дублировал строки и любой период можно было пересчитать","Чтобы данные хранились в одном файле"]', 2, 'Заменяют партицию или вставляют с проверкой ключа: тогда сбой в середине и повторный запуск безопасны.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 26, 4, 'Для чего нужен захват изменений (CDC)?', '["Для шифрования резервных копий","Чтобы читать журнал базы и передавать изменения потоком событий почти без нагрузки на таблицы","Для выбора индекса","Чтобы закрывать долгие транзакции"]', 1, 'События могут прийти повторно, поэтому порядок по ключу сохраняют, а обработку делают идемпотентной.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 27, 'theory', 'Квиз: проектирование схемы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 27, 0, 'Почему первичным ключом обычно делают суррогатный, а не естественный?', '["Суррогатный ключ быстрее читается на диске","Естественных ключей не бывает","Естественный ключ нельзя сделать уникальным","Естественные ключи меняются вместе с реальным миром; суррогатный стабилен, а естественный закрепляют ограничением уникальности"]', 3, 'Номер паспорта могут перевыпустить, страну переименовать; на суррогатный ключ ссылаются другие таблицы, и он не должен меняться.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 27, 1, 'Чем плоха хранение денег в числах с плавающей точкой?', '["Они занимают больше места, чем целые","Дробные доли не представимы точно, и суммы накапливают ошибки округления; нужны целые копейки или точный десятичный тип","Их нельзя сравнивать","Они не поддерживают сложение"]', 1, 'Десять копеек трижды в двоичной дроби не дают ровно тридцать; в расчётах с деньгами такие расхождения недопустимы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 27, 2, 'Какая аномалия возникает, если город клиента повторяется в каждой строке его заказов?', '["Только аномалия вставки","Только аномалия удаления","Аномалии изменения, вставки и удаления: правку надо делать во многих строках, нового клиента без заказа записать некуда, а удаление последнего заказа стирает клиента","Никаких, это быстрее читается"]', 2, 'Решение — вынести город в таблицу клиентов: факт хранится один раз.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 27, 3, 'Что требует третья нормальная форма?', '["Чтобы в таблице не было внешних ключей","Чтобы неключевой столбец не зависел от другого неключевого — только от ключа","Чтобы все таблицы имели составной ключ","Чтобы данные хранились в одной таблице"]', 1, 'Каждый столбец должен зависеть от ключа, от всего ключа и ни от чего, кроме ключа; транзитивные зависимости выносят в отдельную таблицу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 27, 4, 'Когда денормализация оправдана?', '["Всегда, ведь соединения дороги","Никогда","Когда есть доказанная проблема со скоростью чтения или нужно сохранить факт на момент события, а владелец истины и способ согласования определены","Когда нужно сократить число таблиц"]', 2, 'Копия — обязательство её согласовывать; копия цены в заказе — это факт, а не нарушение.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 28, 'theory', 'Квиз: продвинутый SQL');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 28, 0, 'Чем оконная функция отличается от группировки с агрегатом?', '["Оконная функция добавляет значение к каждой строке, не схлопывая их в одну на группу","Оконная функция работает только с текстом","Оконные функции запрещены в SELECT","Группировка не умеет суммировать"]', 0, 'С окном можно показать строку заказа и сумму заказов клиента рядом; GROUP BY оставил бы одну строку на клиента.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 28, 1, 'Как получить три самых дорогих товара в каждой категории?', '["Использовать LIMIT 3 один раз","Сделать GROUP BY category и взять максимум","Пронумеровать строки функцией ROW_NUMBER() OVER (PARTITION BY category ORDER BY price DESC) в подзапросе и оставить номера не выше трёх","Отсортировать таблицу и надеяться на порядок"]', 2, 'Окна вычисляются после WHERE, поэтому условие на номер задают в обёртке или общем выражении.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 28, 2, 'Что делает рамка ROWS BETWEEN 2 PRECEDING AND CURRENT ROW?', '["Суммирует всю таблицу","Выбирает две случайные строки","Удаляет повторы","Берёт текущую строку и две предыдущие — например, для скользящего среднего за три шага"]', 3, 'ROWS считает физические строки, RANGE — значения порядка; при равных значениях это даёт разные результаты.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 28, 3, 'Из каких частей состоит рекурсивное общее выражение и как избежать бесконечного цикла?', '["Только из якоря; циклов не бывает","Из якоря и рекурсивного шага, соединённых UNION ALL; при цикле в данных ограничивают глубину, запоминают путь или используют UNION","Из двух независимых запросов","Из индекса и триггера"]', 1, 'Рекурсия останавливается, когда шаг не даёт новых строк; в данных с циклом без защиты она не закончится.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 28, 4, 'Почему для поиска клиентов без заказов NOT EXISTS надёжнее NOT IN?', '["NOT IN всегда быстрее","NOT EXISTS не работает без индекса","Если в подзапросе NOT IN встретится NULL, он не вернёт ни одной строки, а NOT EXISTS ведёт себя ожидаемо","NOT EXISTS запрещён стандартом"]', 2, 'Сравнение с NULL даёт «неизвестно», поэтому NOT IN при наличии NULL в списке отсеивает все строки.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 29, 'theory', 'Квиз: оптимизатор');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 29, 0, 'На чём основан выбор плана оптимизатором?', '["На порядке слов в запросе","На случайном выборе из возможных","На оценке стоимости, которая опирается на статистику и оценку числа строк","На размере файла журнала"]', 2, 'Оптимизатор перебирает физические планы и выбирает самый дешёвый по своей оценке; ошибка в оценке строк ведёт к плохому плану.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 29, 1, 'Почему оценка для нескольких условий часто бывает неточной?', '["Оптимизатор не умеет считать","Для условий перемножаются доли в предположении независимости, а связанные столбцы (город и индекс) это нарушают","Условия всегда выполняются одновременно","База хранит только одно условие"]', 1, 'Лекарство — расширенная статистика по связанным столбцам и обновление статистики командой ANALYZE.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 29, 2, 'Когда вложенные циклы выгоднее хеш-соединения?', '["Когда внешняя таблица мала, а на внутренней есть подходящий индекс","Когда обе таблицы огромны и без индексов","Когда условие соединения — неравенство и памяти много","Никогда"]', 0, 'Хеш и слияние лучше для больших наборов и равенства; для неравенств подходят только вложенные циклы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 29, 3, 'Что нужно искать в выводе EXPLAIN ANALYZE в первую очередь?', '["Только общее время запроса","Цвет узлов","Количество пробелов","Расхождения оценки и факта на порядок, просмотр большой таблицы вместо поиска и самый дорогой узел"]', 3, 'Начинают с самого дорогого узла и идут вглубь, сравнивая ожидаемое число строк с реальным.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 29, 4, 'Почему подготовленный запрос может внезапно замедлиться для отдельных значений параметра?', '["Закончилась память у клиента","Журнал переполнился","План, оптимальный для частого значения, плох для редкого — общий план не учитывает перекос данных","Индексы удалились"]', 2, 'Решения: индивидуальные планы, отдельные запросы для крайних случаев, настройка режима планирования.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 30, 'theory', 'Квиз: миграции и копии');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 30, 0, 'Что делают, если в уже применённой миграции найдена ошибка?', '["Редактируют файл миграции","Удаляют запись о ней из служебной таблицы","Переустанавливают базу","Пишут новую миграцию, исправляющую ошибку, а старую не трогают"]', 3, 'Применённая миграция неизменна — иначе у разных окружений получатся разные схемы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 30, 1, 'Как переименовать столбец в работающей системе без простоя?', '["Одной командой ALTER … RENAME в любое время","Добавить новый столбец, писать в оба, перенести историю порциями, переключить чтение и удалить старый отдельной миграцией","Остановить все серверы на ночь","Скопировать таблицу целиком"]', 1, 'Каждый шаг совместим и с предыдущей, и со следующей версией кода — выкатку можно остановить в любой точке.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 30, 2, 'Почему один UPDATE по ста миллионам строк опасен?', '["Он держит блокировки, раздувает журнал и при сбое откатывается целиком; лучше обновлять порциями с паузой","Он недоступен в большинстве баз","Он не меняет данные","Он всегда быстрее порций"]', 0, 'Порции делают операцию возобновляемой и дают репликации время догнать.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 30, 3, 'Чем реплика отличается от резервной копии?', '["Ничем, это одно и то же","Реплика защищает от логических ошибок, копия — от отказа железа","Реплика повторяет и ошибочные команды, например удаление таблицы, а копия позволяет вернуться на момент до ошибки","Копия всегда актуальнее реплики"]', 2, 'Нужны оба уровня; копии хранят отдельно от основной системы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 30, 4, 'Что значит «восстановление на момент времени»?', '["Разворачивание копии без журнала","Копирование дампа на новый сервер","Остановка базы на фиксированное время","Развёртывание физической копии и проигрывание архива журнала упреждающей записи до нужного момента"]', 3, 'Так можно вернуться на секунду до ошибочного удаления; частота архивирования журнала определяет допустимую потерю данных.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 31, 'theory', 'Квиз: безопасность');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 31, 0, 'Чем надёжно защищаются от SQL-инъекций?', '["Ручным экранированием кавычек в строках","Параметризованными запросами: текст и значения передаются отдельно, значения не разбираются как код","Запретом использовать апострофы","Шифрованием диска"]', 1, 'Для имён таблиц, столбцов и направления сортировки параметры не годятся — нужен белый список разрешённых значений.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 31, 1, 'Почему приложению нельзя подключаться к базе от имени владельца схемы?', '["Владелец не может читать данные","Это замедляет запросы","У владельца есть право удалять и менять таблицы и обходить защиту строк; приложению нужны минимальные привилегии","Владельцев может быть только один"]', 2, 'Заводят отдельные роли: владелец для миграций, приложение для чтения и записи, отчёты только для чтения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 31, 2, 'Как правильно хранить пароли пользователей приложения?', '["Открытым текстом в отдельной таблице","Обратимым шифрованием общим ключом","Быстрым хешем без соли","Медленным хешем со случайной солью — scrypt, argon2 или bcrypt"]', 3, 'Соль делает одинаковые пароли разными, медленный алгоритм усложняет перебор.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 31, 3, 'Для чего нужна защита на уровне строк (RLS)?', '["Чтобы разные пользователи видели разные строки одной таблицы — политика добавляется к запросу автоматически","Чтобы шифровать резервные копии","Чтобы ускорить соединения","Чтобы запретить индексы"]', 0, 'В многоарендных системах база сама отфильтрует чужие строки, даже если разработчик забыл условие; владелец и суперпользователь обходят политики.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 31, 4, 'От чего защищает шифрование диска и чем его дополнить?', '["От любого взлома; больше ничего не нужно","От кражи носителя и копий; для сети нужен TLS, для защиты от администратора — шифрование полей в приложении","От инъекций","От долгих запросов"]', 1, 'Единого шифрования «на всё» не бывает: важно понимать, от кого защищаетесь, и хранить ключи отдельно от данных.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 32, 'theory', 'Квиз: база в приложении');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 32, 0, 'Что такое проблема «N плюс один» и как её лечат?', '["Нехватка памяти; увеличивают кэш","Один запрос за списком и по запросу на каждый элемент; лечат жадной загрузкой (соединение или запрос со списком идентификаторов)","Ошибка соединения; перезапускают приложение","Блокировка таблицы; завершают транзакции"]', 1, 'Журнал показывает один и тот же шаблон запроса, повторённый десятки раз; один запрос вместо N снижает задержку на порядки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 32, 1, 'Почему слишком большой пул соединений вреден?', '["Ничего плохого, чем больше, тем быстрее","Он занимает память клиента","Сервер базы выполняет эффективно лишь столько запросов, сколько у него ресурсов; остальные конкурируют за них, и пул скрывает проблему","Он запрещён протоколом"]', 2, 'Закон Литтла: число одновременных запросов = интенсивность × среднее время; размер подбирают измерениями.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 32, 2, 'Что делает операцию идемпотентной при повторах клиента?', '["Увеличение времени ожидания","Запрет повторов на стороне клиента","Отключение транзакций","Ключ идемпотентности: результат записывается с ключом в одной транзакции, а при повторе возвращается прежний"]', 3, 'Сети ненадёжны, клиенты повторяют запросы; повтор не должен удваивать списание или заказ.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 32, 3, 'Для чего нужен шаблон «исходящие сообщения» (outbox)?', '["Чтобы событие записывалось в таблицу в той же транзакции, что и бизнес-изменение, и затем надёжно публиковалось отдельным процессом","Чтобы ускорить чтение","Чтобы шифровать данные","Чтобы уменьшить число индексов"]', 0, 'Так нельзя получить изменение без события или событие без изменения; доставка «как минимум один раз» требует идемпотентных потребителей.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 32, 4, 'Как избежать чтения устаревших данных с реплики сразу после записи пользователя?', '["Никогда не писать","Читать с реплики всегда","Читать свои записи с основной базы короткое время после изменения или привязать сеанс к основной базе","Отключить репликацию"]', 2, 'Реплика отстаёт; критичные для корректности чтения идут на основную базу, маршрутизацию делают явно.');
